@startuml

class Bettor {
  + name : string
  + id : int
}

class Jockey {
  + name : string
  + id : int
}

class Horse {
  + name : string
  + id : int
}

class Race {
  + id : int
  + winner : Runner
}

class Runner {
  + horse : Horse
  + jockey : Jockey
}

class Bet {
  + amount : double
  + odds : double
  + bettor : Bettor
  + race : Race
  + runner : Runner
}

Bettor "1" -- "*" Bet : places
Jockey "1" -- "*" Horse : rides
Horse "1" -- "*" Runner : participates
Race "1" *-- "*" Runner : contains
Runner "0..1" -- "1" Race : isWinnerOf
Bookmaker "1" -- "*" Bet : accepts

@enduml

